175	export function endingOf(signals: TurnSignals): TurnEnding {
176	  const named = signals.directive.trim();
177	  const next = named === "" ? undefined : { agent: named };
178	
179	  if (!signals.succeeded || signals.endedBecause === "failed") return { ended: "failed" };
180	  if (signals.endedBecause === "loop") return { ended: "looped" };
181	  if (signals.endedBecause === "stopped") return { ended: "stopped" };
182	  if (signals.endedBecause === "iterations" || signals.endedBecause === "runtime") return { ended: "spent" };
183	  if (signals.loopLimitReached) return { ended: "chain-over", ...(next ? { next } : {}) };
184	  if (next || signals.chainContinues) return { ended: "handed-off", ...(next ? { next } : {}) };
185	  if (!signals.reported) return { ended: "no-report" };
186	  return { ended: "finished" };
